<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Database;
use App\Services\DanceCupScoringService;
$token=preg_replace('/[^a-f0-9]/','',(string)($_GET['token']??''));
$test=(string)($_GET['data_mode']??'')==='test';
if(strlen($token)!==64){http_response_code(404);exit('Projector link not found.');}
$initialEventName='Dance Cup';
try{
 $prefix=$test?'bdc_test_dance_cup':'bdc_dance_cup';$tables=DanceCupScoringService::tables($test);
 $initial=Database::connection()->prepare("SELECT e.name FROM {$prefix}_event_projection p JOIN {$tables['events']} e ON e.id=p.event_id WHERE p.access_token=:token LIMIT 1");
 $initial->execute(['token'=>$token]);$initialEventName=(string)($initial->fetchColumn()?:$initialEventName);
}catch(Throwable){}
header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
header('Pragma: no-cache');
header('Expires: 0');
