.grid:has(>.judge-card:nth-child(4)){grid-template-columns:repeat(4,minmax(0,1fr))!important}
.grid:has(>.judge-card:nth-child(5)){grid-template-columns:repeat(5,minmax(0,1fr))!important}
.grid:has(>.judge-card:nth-child(6)){grid-template-columns:repeat(6,minmax(0,1fr))!important}
.grid:has(>.judge-card:nth-child(7)){grid-template-columns:repeat(4,minmax(0,1fr))!important}
.grid:has(>.judge-card:nth-child(9)){grid-template-columns:repeat(5,minmax(0,1fr))!important}
.grid:has(>.judge-card:nth-child(11)){grid-template-columns:repeat(6,minmax(0,1fr))!important}
.grid:has(>.judge-card)>.judge-card{min-height:0!important;padding:clamp(8px,.75vw,14px)!important}
.grid:has(>.judge-card) .profile-photo{width:clamp(61px,min(8.8vw,9.6vh),106px)!important;height:clamp(76px,min(11vw,12vh),132px)!important;margin-bottom:clamp(4px,.55vh,8px)!important}
.grid:has(>.judge-card) .kicker{font-size:clamp(10px,.68vw,14px)!important;line-height:1!important}
.grid:has(>.judge-card) strong{font-size:clamp(18px,1.45vw,29px)!important;line-height:1!important;white-space:nowrap!important;overflow:hidden!important;text-overflow:ellipsis!important}
.grid:has(>.judge-card) .identity-meta{font-size:clamp(11px,.76vw,16px)!important;white-space:nowrap!important;overflow:hidden!important;gap:clamp(4px,.32vw,7px)!important}
.grid:has(>.judge-card) .identity-country{max-width:100%!important;flex:0 1 auto!important;overflow:hidden!important}
.grid:has(>.judge-card) .identity-country>span:last-child{min-width:0!important;overflow:hidden!important;text-overflow:ellipsis!important;white-space:nowrap!important}
.grid:has(>.judge-card) .judge-status-stack{gap:clamp(2px,.28vh,4px)!important;margin-top:clamp(4px,.55vh,8px)!important}
.grid:has(>.judge-card) .judge-status-stack .status{font-size:clamp(9px,.58vw,12px)!important;padding:.3em .5em!important;white-space:nowrap!important;overflow:hidden!important;text-overflow:ellipsis!important}

/* Canonical 4:5 profile preview: projector shows the saved crop without an
   additional circle mask or hidden zoom. */
.podium-card.second .podium-photo,.podium-card.third .podium-photo{width:clamp(58px,4.8vw,86px);height:clamp(72px,6vw,108px)}
@media(max-aspect-ratio:1/1){.call .profile-photo{width:clamp(152px,19.2vw,224px);height:clamp(190px,24vw,280px)}}
@media(max-width:640px){.call .profile-photo{width:clamp(120px,30.4vw,176px);height:clamp(150px,38vw,220px)}}

/* Dance Cup one-by-one judge introduction. The all-judges and scoring grids
   keep their existing count-adaptive sizing. */
.judge-call{width:100%;height:100%;display:grid;place-items:center}
.judge-call-card{width:min(980px,72vw);height:min(100%,650px);padding:clamp(22px,2.4vw,46px)!important;border-top:clamp(6px,.55vw,10px) solid var(--accent);background:radial-gradient(circle at 50% 30%,color-mix(in srgb,var(--card) 72%,var(--accent) 10%),var(--card));overflow:hidden}
.judge-call-card>div{height:100%;min-height:0;display:flex;flex-direction:column;align-items:center;justify-content:center}
.judge-call-card .profile-photo{width:clamp(210px,min(20vw,34vh),350px)!important;height:clamp(262px,min(25vw,42.5vh),438px)!important;margin:0 0 clamp(10px,1.5vh,20px)!important;border-width:clamp(3px,.3vw,5px)!important}
.judge-call-card .kicker{font-size:clamp(16px,1.25vw,24px)!important;line-height:1.1!important}
.judge-call-card strong{font-size:clamp(40px,4vw,76px)!important;line-height:1.02!important;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.judge-call-card .identity-meta{margin-top:clamp(8px,1.15vh,16px);font-size:clamp(19px,1.65vw,31px);font-weight:900;color:var(--text);gap:clamp(10px,1vw,18px)}
.judge-call-card .identity-country{overflow:visible}.judge-call-card .identity-country .flag-image{width:clamp(42px,3.4vw,66px)}
@media(max-aspect-ratio:1/1){.judge-call-card{width:min(88vw,760px)}.judge-call-card .profile-photo{width:clamp(190px,38vw,320px)!important;height:clamp(237px,47.5vw,400px)!important}}

</style>
</head>
<body class="dc-projector-presentation">
<main id="app">
 <header class="top"><div class="event-brand"><div class="logo"><img src="../../public/assets/img/bdc-logo.png" alt="BDC"></div><div class="event"><h1 id="eventName"><?=htmlspecialchars($initialEventName,ENT_QUOTES,'UTF-8')?></h1><p id="categoryName"></p></div></div><div class="identity"><span class="official <?=$test?'test':''?>" data-dc-fullscreen-ready="1" role="button" tabindex="0" title="Enter full screen" aria-label="Enter full screen"><?=$test?'TEST DISPLAY':'BDC · OFFICIAL LIVE DISPLAY'?></span></div></header>
 <section class="stage" id="stage"><div class="view"><div class="holding"><h2><?=htmlspecialchars($initialEventName,ENT_QUOTES,'UTF-8')?></h2></div></div></section>
 <footer class="footer"><span class="state" id="screenState">Holding Screen</span><span class="page" id="pageState"></span><span class="live"><i class="dot"></i>Live</span></footer>
</main>
<div class="connection" id="connection">Live updates temporarily unavailable. Retrying…</div>
<div class="fx-layer" id="fxLayer" aria-hidden="true"></div>
<script>
(()=>{'use strict';
const token=<?=json_encode($token)?>,test=<?=$test?'true':'false'?>,stage=document.getElementById('stage'),eventName=document.getElementById('eventName'),categoryName=document.getElementById('categoryName'),screenState=document.getElementById('screenState'),pageState=document.getElementById('pageState'),connection=document.getElementById('connection'),fxLayer=document.getElementById('fxLayer');
let lastHash='',lastRevision='',busy=false,pollTimer=null,currentPage=1,pageTotal=1,lastType='holding',nextPageAt=0,backoffUntil=0,lastEffectVersion=0,effectRun=0,revealCountdownTimer=null,cycle={index:0,phase:'contestant',next:0},latest=null;
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const label=value=>String(value||'').replace(/\brising\b/gi,'Intermediate').replaceAll('_',' ').replace(/\b\w/g,char=>char.toUpperCase());
const chunk=(items,size)=>{const pages=[];for(let index=0;index<items.length;index+=size)pages.push(items.slice(index,index+size));return pages.length?pages:[[]]};
const empty=(title,message)=>'<div class="empty"><strong>'+esc(title)+'</strong><span>'+esc(message)+'</span></div>';
function setHeader(data){document.body.dataset.theme=data.state.theme||'midnight_wine';eventName.textContent=data.state.event_name||'BDC Dance Cup';categoryName.textContent='';}
const photo=item=>esc(item?.photo_url||'../../public/assets/img/default-competitor.svg');
const identity=item=>{const countries=Array.isArray(item?.countries)&&item.countries.length?item.countries:[item?.country].filter(Boolean),flags=Array.isArray(item?.flags)?item.flags:[],codes=Array.isArray(item?.country_codes)?item.country_codes:[];if(!countries.length)return '<div class="identity-meta"><span>Country not set</span></div>';return '<div class="identity-meta multi-country">'+countries.slice(0,5).map((country,index)=>{const code=String(codes[index]||'').toLowerCase().replace(/[^a-z]/g,'');const flag=code?'<img class="flag-image" src="../../public/assets/flags/'+esc(code)+'.svg" alt="'+esc(country)+' flag">':'<span class="flag">'+esc(flags[index]||'')+'</span>';return '<span class="identity-country">'+flag+'<span>'+esc(country)+'</span></span>'}).join('')+'</div>'};
function show(html,type,page=0,total=0){pageTotal=Math.max(1,total||1);const category=label(latest?.state?.category_name||'Dance Cup Category')+' · '+label(latest?.state?.round_name||'');stage.innerHTML='<div class="view"><div class="screen-category">'+esc(category)+'</div><div class="screen-content">'+html+'</div></div>';screenState.textContent=label(type);pageState.textContent=total>1?'Page '+page+' of '+total:'';}
function holding(data){stage.innerHTML='<div class="view" style="grid-template-rows:1fr"><div class="screen-content"><div class="holding"><h2>'+esc(data.state.event_name||'Dance Cup')+'</h2></div></div></div>';screenState.textContent='Holding Screen';pageState.textContent='';}
function contestant(entry){const eventLabel=latest?.state?.event_name||'Dance Cup';show(entry?'<div class="call"><div class="call-layout"><section class="number-panel"><div class="number-label">Contestant Number</div><div class="number">'+esc(entry.contestant_number)+'</div></section><section class="contestant-identity"><img class="profile-photo" src="'+photo(entry)+'" alt=""><div class="label">NOW PRESENTING</div><h2>'+esc(entry.display_name)+'</h2>'+identity(entry)+'</section><aside class="trophy-showcase"><img src="../../public/assets/img/sbta-dance-cup-champion-trophy.png" alt="SBTA Dance Cup trophy"><strong>'+esc(eventLabel)+'</strong></aside></div></div>':empty('Contestant pending','Select a contestant from Projection Control.'),'Contestant Call');}
function pagedCards(items,size,type,renderCard,data){const pages=chunk(items,size),total=pages.length;currentPage=Math.max(1,Math.min(total,currentPage));const cards=pages[currentPage-1].map(renderCard).join('');show(cards?'<div class="grid '+(size>=10?'compact':'')+'">'+cards+'</div>':empty(type+' pending','Add records in the Dance Cup category workspace.'),type,currentPage,total);schedulePage(total,data);}
function judgeCall(data){const total=data.judges.length;currentPage=Math.max(1,Math.min(Math.max(1,total),currentPage));const judge=data.judges[currentPage-1];const card=judge?'<div class="judge-call"><article class="card judge-card judge-call-card"><div><img class="profile-photo" src="'+photo(judge)+'" alt=""><span class="kicker">J'+esc(judge.judge_order)+(Number(judge.is_chief)?' · Chief Judge':' · Judge')+'</span><strong>'+esc(judge.judge_name)+'</strong>'+identity(judge)+'</div></article></div>':empty('Judge Call pending','Assign judges in the Dance Cup category workspace.');show(card,'Calling Judges',currentPage,Math.max(1,total));schedulePage(total,data);}
function judges(data,progress=false){const contestantDone=data.judges.filter(j=>j.contestant_status==='complete').length,finalDone=data.judges.filter(j=>Number(j.final_submitted)===1).length,bib=(data.progress_entry||data.active_entry)?.contestant_number;const cards=j=>{const current=j.contestant_status||'pending',currentText=current==='complete'?'Completed · No. '+(bib||'—'):current==='in_progress'?'Scoring · No. '+(bib||'—'):'Pending · No. '+(bib||'—');return '<article class="card judge-card contestant-'+esc(current.replace('_','-'))+'"><div><img class="profile-photo" src="'+photo(j)+'" alt=""><span class="kicker">J'+esc(j.judge_order)+(Number(j.is_chief)?' · Chief Judge':'')+'</span><strong>'+esc(j.judge_name)+'</strong>'+identity(j)+'<div class="judge-status-stack"><small class="status current '+esc(current.replace('_','-'))+'">'+esc(currentText)+'</small><small class="status final '+(Number(j.final_submitted)===1?'submitted':'pending')+'">'+(Number(j.final_submitted)===1?'Final submitted':'Final pending')+'</small></div></div></article>'};if(progress){const pages=chunk(data.judges,8),total=pages.length;currentPage=Math.max(1,Math.min(total,currentPage));show('<div class="progress-wrap"><div class="progress-summary"><span>Contestant No. '+esc(bib||'—')+': <b>'+contestantDone+' / '+data.judges.length+'</b> judges complete</span><span class="waiting">Final submission: '+finalDone+' / '+data.judges.length+'</span></div><div class="grid">'+pages[currentPage-1].map(cards).join('')+'</div></div>','Scoring Progress',currentPage,total);schedulePage(total,data);}else pagedCards(data.judges,Math.max(1,data.judges.length),'Judges',cards,data);}
function contestants(data){const pages=chunk(data.entries,10),total=pages.length;currentPage=Math.max(1,Math.min(total,currentPage));const page=pages[currentPage-1],rows=Math.max(1,Math.ceil(page.length/5)),cards=page.map(entry=>'<article class="card contestant-card"><div><span class="contestant-photo-frame"><img class="profile-photo" src="'+photo(entry)+'" alt=""></span><span class="kicker">Contestant</span><strong class="bib">'+esc(entry.contestant_number)+'</strong><small class="contestant-name">'+esc(entry.display_name)+'</small>'+identity(entry)+'</div></article>').join('');show(cards?'<div class="grid compact contestant-grid rows-'+rows+'">'+cards+'</div>':empty('All Contestants pending','Add records in the Dance Cup category workspace.'),'All Contestants',currentPage,total);schedulePage(total,data);}
function results(data){const pages=chunk(data.results,8),total=pages.length;currentPage=Math.max(1,Math.min(total,currentPage));const rows=pages[currentPage-1].map(row=>{const scored=Number(row.has_score)===1;return '<div class="rank-row"><span class="place">'+(scored?esc(row.placement):'—')+'</span><img class="rank-photo" src="'+photo(row)+'" alt=""><span class="number">No. '+esc(row.contestant_number)+'</span><span class="name">'+esc(row.display_name)+' '+esc(row.flag||'')+'</span><span class="score">'+(scored?Number(row.total_score).toLocaleString(undefined,{maximumFractionDigits:2}):'Not scored')+'</span></div>'}).join('');show(rows?'<div class="board">'+rows+'</div>':empty('Scores pending','Scores will appear after judges begin scoring.'),'Live Scoreboard',currentPage,total);schedulePage(total,data);}
function podium(data){const top=data.results.filter(row=>Number(row.has_score)===1&&row.placement!==null).slice(0,3),order=[top[1],top[0],top[2]],classes=['second','first','third'],medals=['🥈','🥇','🥉'],reveal=String(data.state.reveal_place||'3');const cards=order.map((row,index)=>{if(!row)return '';const visible=reveal==='all'||Number(row.placement)>=Number(reveal);return '<article class="podium-card '+classes[index]+(visible?'':' hidden-slot')+'"><div class="medal">'+medals[index]+'</div><img class="podium-photo" src="'+photo(row)+'" alt=""><div class="place">'+label(row.placement+(Number(row.placement)===1?'st':Number(row.placement)===2?'nd':'rd'))+'</div><div class="number">No. '+esc(row.contestant_number)+'</div><div class="name">'+esc(row.display_name)+'</div>'+identity(row)+'<div class="score">'+Number(row.total_score).toLocaleString(undefined,{maximumFractionDigits:2})+' points</div></article>'}).join('');show(cards?'<div class="podium">'+cards+'</div>':empty('Podium locked','Calculate results before revealing the winners.'),'Winner Podium');}
function countdownToPodium(data){if(revealCountdownTimer)clearInterval(revealCountdownTimer);let seconds=5;const place=String(data.state.reveal_place||'3'),placeText=place==='1'?'Champion':place==='2'?'2nd Place':'3rd Place';const paint=()=>{stage.innerHTML='<div class="result-countdown"><div><div class="count-label">Result Reveal</div><div class="count-number">'+seconds+'</div><div class="count-place">'+placeText+'</div></div></div>';screenState.textContent='Result Countdown';pageState.textContent='';};paint();revealCountdownTimer=setInterval(()=>{seconds-=1;if(seconds>0){paint();return}clearInterval(revealCountdownTimer);revealCountdownTimer=null;podium(data);playEffect(data.state);},1000);}
function schedulePage(total,data){pageTotal=Math.max(1,total||1);if(total<2){nextPageAt=0;return}if(Number(data.state.auto_page)){if(!nextPageAt)nextPageAt=Date.now()+Math.max(5,Number(data.state.page_delay)||10)*1000}else nextPageAt=0;}
function clearEffectAfter(run,milliseconds){setTimeout(()=>{if(run===effectRun)fxLayer.innerHTML=''},milliseconds)}
function launchFireworks(count=26,run=effectRun){const colours=['#f6c945','#ff4d6d','#6ee7ff','#9b7bff','#fff4bd','#65f29a'];for(let burstIndex=0;burstIndex<count;burstIndex++){setTimeout(()=>{if(run!==effectRun)return;const burst=document.createElement('div');burst.className='firework-burst';burst.style.left=(10+Math.random()*80)+'vw';burst.style.top=(10+Math.random()*62)+'vh';const colour=colours[burstIndex%colours.length];for(let sparkIndex=0;sparkIndex<24;sparkIndex++){const spark=document.createElement('i');spark.className='firework-spark';spark.style.setProperty('--spark',colour);spark.style.setProperty('--angle',(sparkIndex*15)+'deg');spark.style.setProperty('--distance',(95+Math.random()*150)+'px');burst.appendChild(spark)}fxLayer.appendChild(burst);setTimeout(()=>burst.remove(),2400)},350+burstIndex*340)}}
function playEffect(state){const version=Number(state.effect_version||0);if(!version||version===lastEffectVersion)return;lastEffectVersion=version;const run=++effectRun;fxLayer.innerHTML='';const type=state.effect_type||'none';if(type==='none')return;fxLayer.innerHTML='<div class="fx-cinematic"></div>';if(type==='fireworks'){launchFireworks(26,run);clearEffectAfter(run,12000);return}if(type==='champion_impact'){fxLayer.insertAdjacentHTML('beforeend','<div class="fx-impact">🏆</div>');clearEffectAfter(run,7600);return}const symbols={hearts:['💖','💗','❤️'],balloons:['🎈','🎈','🎈'],heart_smiles:['🥰','😍','💖'],finger_hearts:['🫰','🫰🏻','🫰🏽'],gold_rain:['✨','⭐','🌟']}[type]||['✨'];for(let i=0;i<84;i++){const particle=document.createElement('span');particle.className='fx-particle';particle.textContent=symbols[i%symbols.length];particle.style.left=(Math.random()*100)+'vw';particle.style.setProperty('--duration',(6.5+Math.random()*3.5)+'s');particle.style.setProperty('--drift',((Math.random()-.5)*34)+'vw');particle.style.animationDelay=(Math.random()*2.4)+'s';fxLayer.appendChild(particle)}clearEffectAfter(run,11200);}
function render(data,force=false){const previous=latest;latest=data;setHeader(data);let type=data.state.screen_type||'holding';if((type==='results'||type==='podium')&&!Number(data.state.results_unlocked))type='holding';const revealChanged=type==='podium'&&force&&(!previous||previous.state.screen_type!=='podium'||String(previous.state.reveal_place)!==String(data.state.reveal_place));if(type!==lastType){lastType=type;currentPage=Math.max(1,Number(data.state.page_number)||1);nextPageAt=0}else if(force)currentPage=Math.max(1,Number(data.state.page_number)||currentPage);if(revealChanged){countdownToPodium(data);return}if(type==='holding')holding(data);else if(type==='contestant')contestant(data.active_entry);else if(type==='contestants')contestants(data);else if(type==='judge_call')judgeCall(data);else if(type==='judges')judges(data,false);else if(type==='scoring')judges(data,true);else if(type==='results')results(data);else if(type==='podium')podium(data);else holding(data);playEffect(data.state);}
function advanceAutoPage(){if(!latest||!nextPageAt||Date.now()<nextPageAt)return;currentPage=currentPage>=pageTotal?1:currentPage+1;nextPageAt=0;render(latest);}
function advanceRunOfShow(data){if(!Number(data.state.auto_cycle)||!data.entries.length)return;if(!cycle.next){cycle.index=Math.max(0,data.entries.findIndex(entry=>Number(entry.id)===Number(data.state.active_entry_id)));cycle.phase='contestant';cycle.next=Date.now()+Number(data.state.contestant_seconds||12)*1000}if(Date.now()<cycle.next)return;if(cycle.phase==='contestant'){cycle.phase='holding';cycle.next=Date.now()+Number(data.state.holding_seconds||8)*1000;holding(data)}else{cycle.phase='contestant';cycle.index=(cycle.index+1)%data.entries.length;cycle.next=Date.now()+Number(data.state.contestant_seconds||12)*1000;contestant(data.entries[cycle.index])}}
function schedulePoll(delay=1000){clearTimeout(pollTimer);pollTimer=setTimeout(poll,delay)}
async function poll(){if(document.hidden||busy){schedulePoll(1000);return}if(Date.now()<backoffUntil){schedulePoll(Math.max(1000,backoffUntil-Date.now()));return}busy=true;const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),7000);let nextDelay=1000;try{const since=lastRevision?'&since='+encodeURIComponent(lastRevision):'';const response=await fetch('./projection-feed.php?token='+encodeURIComponent(token)+(test?'&data_mode=test':'')+since+'&_='+Date.now(),{cache:'no-store',credentials:'same-origin',headers:{Accept:'application/json'},signal:controller.signal});if(response.status===429){backoffUntil=Date.now()+10000;nextDelay=10000;throw new Error('Rate limited')}const contentType=response.headers.get('content-type')||'';if(!contentType.includes('application/json'))throw new Error('Invalid feed response');const data=await response.json();if(!response.ok||!data.ok)throw new Error('Feed unavailable');if(data.revision)lastRevision=String(data.revision);if(data.unchanged){if(latest)advanceRunOfShow(latest);connection.style.display='none';return}const hash=JSON.stringify([data.state.state_version,data.state.screen_type,data.state.theme,data.state.page_number,data.state.auto_page,data.state.page_delay,data.entries,data.judges,data.results,data.active_entry,data.progress_entry]);if(hash!==lastHash){const stateChanged=lastHash!==''&&latest&&Number(data.state.state_version)!==Number(latest.state.state_version);lastHash=hash;render(data,stateChanged);cycle.next=0}advanceRunOfShow(data);connection.style.display='none'}catch(error){nextDelay=Math.max(nextDelay,2500);connection.textContent=error?.name==='AbortError'?'Live update timed out. Retrying…':'Live updates interrupted. Retrying…';connection.style.display='block'}finally{clearTimeout(timeout);busy=false;schedulePoll(nextDelay)}}
setInterval(advanceAutoPage,500);poll();document.addEventListener('visibilitychange',()=>{if(!document.hidden){clearTimeout(pollTimer);poll()}});
})();
</script>
<script>
(function(){
 const badge=document.querySelector('[data-dc-fullscreen-ready="1"]');
 if(!badge)return;
 const enter=()=>{if(document.fullscreenElement)return;const root=document.documentElement,request=root.requestFullscreen||root.webkitRequestFullscreen;if(request){const result=request.call(root);if(result&&typeof result.catch==='function')result.catch(()=>{});}};
 badge.addEventListener('click',enter);
 badge.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();enter();}});
})();
</script>
</body>
